package com.campuseventhub;
import java.io.IOException;import java.sql.Connection;import java.sql.PreparedStatement;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;
@WebServlet("/deleteEvent") public class DeleteEventServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{HttpSession s=r.getSession(false);if(s==null||s.getAttribute("admin_id")==null){p.sendRedirect("admin-login.jsp");return;}try(Connection c=DBConnection.getConnection();PreparedStatement x=c.prepareStatement("DELETE FROM events WHERE event_id=?")){x.setInt(1,Integer.parseInt(r.getParameter("event_id")));x.executeUpdate();p.sendRedirect("viewEvents");}catch(Exception e){p.setContentType("text/html;charset=UTF-8");p.getWriter().println("<h2>Error: "+e.getMessage()+"</h2>");}}}
